        "localizador": "L02"
      }
    ],
    "lacunas": [
      "Faltam as relações de precedência necessárias para comparar o término novo com D12."
    ],
    "motivo": "Sem o término novo calculável, não se determina a variação em dias.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
