        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "A linha base declarada fixa o custo em R$ 1.650,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_113c08",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "O custo do apoio depende do término final, que não pode ser calculado sem as precedências."
    ],
    "motivo": "As parcelas fixas permanecem, não há cobrança direta no aviso e o custo variável do apoio depende da duração até o marco final.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "Faltam as precedências para apurar o término novo e, consequentemente, a extensão do apoio e a variação do custo."
    ],
    "motivo": "A política sem crédito e a tarifa de extensão não bastam para calcular a variação sem conhecer o término novo.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "O aviso substitui as durações de preparar suporte e usinar corpo, sem cobrança direta. A ficha de precedências é mencionada, mas suas relações não estão visíveis; portanto, não se pode calcular o término novo nem o custo variável do apoio."
}

